package com.tanidikvar.api.report.controller;
import com.tanidikvar.api.report.dto.*;import com.tanidikvar.api.report.service.QuestionReportService;import com.tanidikvar.api.auth.security.SessionPrincipal;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController public class QuestionReportController{private final QuestionReportService reports;public QuestionReportController(QuestionReportService reports){this.reports=reports;}@PostMapping("/api/questions/{id}/reports")@ResponseStatus(HttpStatus.CREATED)public QuestionReportResponse create(@AuthenticationPrincipal SessionPrincipal p,@PathVariable UUID id,@Valid @RequestBody QuestionReportRequest request){return reports.create(p.userId(),id,request);}@PostMapping("/api/answers/{id}/reports")@ResponseStatus(HttpStatus.CREATED)public ContentReportResponse answer(@AuthenticationPrincipal SessionPrincipal p,@PathVariable UUID id,@Valid @RequestBody QuestionReportRequest request){return reports.createContent(p.userId(),"ANSWER",id,request);}@PostMapping("/api/answer-comments/{id}/reports")@ResponseStatus(HttpStatus.CREATED)public ContentReportResponse comment(@AuthenticationPrincipal SessionPrincipal p,@PathVariable UUID id,@Valid @RequestBody QuestionReportRequest request){return reports.createContent(p.userId(),"ANSWER_COMMENT",id,request);}}
